async function main() {
  const apiKey = process.env.COMPOSIO_API_KEY;
  if (!apiKey) {
    throw new Error("Missing COMPOSIO_API_KEY environment variable.");
  }

  const composio = new Composio({ apiKey });

  // Create a session for the user (uses a dedicated Composio instance).
  const session = composio.createSession({
    headers: {
      "x-composio-user-id": userId,
    },
  });

  console.log("Listing GitHub trigger types...");
  const triggerTypes = await session.triggers.listTypes({ toolkits: ["github"] });

  const triggerType =
    triggerTypes.items.find((item) => item.slug.includes("GITHUB_ISSUE")) ||
    triggerTypes.items.find((item) => item.slug.toLowerCase().includes("issue")) ||
    triggerTypes.items[0];

  if (!triggerType) {
    throw new Error("No GitHub trigger types found.");
  }

  console.log("Selected trigger type:", triggerType.slug);

  console.log("Creating trigger instance...");
  const createdTrigger = await session.triggers.create(userId, triggerType.slug);
  const triggerId = createdTrigger.triggerId;

  console.log("Created trigger ID:", triggerId);

  console.log("Disabling trigger instance...");
  await session.triggers.disable(triggerId);

  console.log("Fetching trigger status...");
  const activeTriggers = await session.triggers.listActive({
    triggerIds: [triggerId],
    showDisabled: true,
  });

  const triggerRecord = activeTriggers.items.find((item) => item.id === triggerId) || null;
  const isActive = triggerRecord ? triggerRecord.disabledAt === null : false;

  if (isActive) {
    console.log("Trigger is still active.");
  } else {
    console.log("Trigger is disabled.");
  }

  const statusPayload = {
    userId,
    triggerType: triggerType.slug,
    triggerId,
    disabledAt: triggerRecord?.disabledAt ?? null,
    isActive,
    triggerRecord,
  };

  await writeFile("/home/user/trigger_status.json", JSON.stringify(statusPayload, null, 2));
  console.log("Saved status to /home/user/trigger_status.json");
}

main().catch((error) => {
  console.error("Trigger workflow failed:", error);
  process.exitCode = 1;
});

